import {categories,colors,effects,defaults,dimensions,validateContent} from './data.js';
import {renderFrame} from './renderer.js';
import {toPNG,download,exportSequence} from './exporter.js';
const $=id=>document.getElementById(id);
const read=key=>{try{const v=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(v)?v.filter(id=>effects.some(e=>e.id===id)):[];}catch{return [];}};
let selected=effects[0],settings=defaults(selected),favorites=new Set(read('motion:favorites')),recent=read('motion:recent');
let view='all',category='all',query='',style='all',playing=!matchMedia('(prefers-reduced-motion: reduce)').matches,progress=.3,lastTime=0,hover=null,toastTimer,exportController=null,lastExport=null,lastDownloadUrl=null;
const notify=message=>{$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3000);};
const persist=()=>{try{localStorage.setItem('motion:favorites',JSON.stringify([...favorites]));localStorage.setItem('motion:recent',JSON.stringify(recent));}catch{notify('当前浏览器无法保存收藏，本次仍可正常使用。');}};
function state(){return {selectedId:selected.id,effectName:selected.name,settings:{...settings,image:settings.image?'local image':null},visibleIds:filtered().map(e=>e.id),favorites:[...favorites],playing,progress,lastExport};}
function filtered(){return effects.filter(e=>(view!=='favorites'||favorites.has(e.id))&&(view!=='recent'||recent.includes(e.id))&&(category==='all'||e.category===category)&&(style==='all'||e.style===style)&&(!query||`${e.name} ${e.style} ${categories.find(c=>c[0]===e.category)[2]} ${e.title}`.toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>view==='recent'?recent.indexOf(a.id)-recent.indexOf(b.id):0);}
function favorite(id){favorites.has(id)?favorites.delete(id):favorites.add(id);persist();renderLibrary();syncFavorite();}
function syncFavorite(){$('favoriteCount').textContent=favorites.size;$('favoriteButton').setAttribute('aria-pressed',favorites.has(selected.id));$('favoriteButton').textContent=favorites.has(selected.id)?'♥':'♡';}
function renderLibrary(){
 hover=null;const list=filtered();$('effectGrid').replaceChildren();$('resultCount').textContent=`${list.length} 个`;$('emptyState').hidden=list.length>0;
 $('resultTitle').textContent=category!=='all'?categories.find(c=>c[0]===category)[2]:view==='favorites'?'我的收藏':view==='recent'?'最近使用':'全部动效';
 $('pageTitle').textContent=view==='favorites'?'好动效，随时再用。':view==='recent'?'继续你的创作。':'让画面，多一点精彩。';
 $('pageSubtitle').textContent=view==='favorites'?'你的常用动效，保存在这个浏览器里。':view==='recent'?'最近选择过的动效，都在这里。':'选一个喜欢的动效，换上你的内容。';
 for(const e of list){const article=document.createElement('article');article.className='effect-card';const button=document.createElement('button');button.className='effect-select';button.dataset.effect=e.id;button.setAttribute('aria-label',`试用${e.name}`);button.setAttribute('aria-pressed',e.id===selected.id);
 const thumb=document.createElement('div');thumb.className='thumb';thumb.style.background=`linear-gradient(145deg, ${e.color}22, #1b2026)`;const canvas=document.createElement('canvas');canvas.width=480;canvas.height=320;canvas.setAttribute('aria-hidden','true');thumb.append(canvas);
 const alpha=document.createElement('span');alpha.className='card-alpha';alpha.textContent='▧';const duration=document.createElement('span');duration.className='duration-pill';duration.textContent='3.0s';thumb.append(alpha,duration);
 const info=document.createElement('div');info.className='card-info';const title=document.createElement('span');title.className='card-title';title.textContent=e.name;const arrow=document.createElement('span');arrow.textContent='↗';info.append(title,arrow);const desc=document.createElement('div');desc.className='card-category';desc.textContent=`${e.style} · ${categories.find(c=>c[0]===e.category)[2]}`;button.append(thumb,info,desc);button.onclick=()=>selectEffect(e.id,true);
 button.onpointerenter=()=>hover={canvas,e,start:performance.now()};button.onpointerleave=()=>{hover=null;renderFrame(canvas,e,defaults(e),e.category==='transition'?.28:.48);};button.onfocus=()=>hover={canvas,e,start:performance.now()};button.onblur=button.onpointerleave;
 const star=document.createElement('button');star.className='card-favorite';star.setAttribute('aria-label',`收藏${e.name}`);star.setAttribute('aria-pressed',favorites.has(e.id));star.textContent=favorites.has(e.id)?'♥':'♡';star.onclick=()=>favorite(e.id);article.append(button,star);$('effectGrid').append(article);renderFrame(canvas,e,defaults(e),e.category==='transition'?.28:.48);
 }
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view&&category==='all'));document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===category));syncFavorite();
}
function selectEffect(id,scroll=false){const e=effects.find(e=>e.id===id);if(!e)throw new Error('未找到该动效');selected=e;settings=defaults(e);recent=[id,...recent.filter(x=>x!==id)].slice(0,24);persist();progress=.05;syncControls();renderLibrary();if(scroll&&innerWidth<=700)document.querySelector('.inspector').scrollIntoView({behavior:'smooth',block:'start'});}
function validate(show=true){const error=validateContent(selected,settings.title);if(show){$('titleError').textContent=error;$('titleError').hidden=!error;$('titleInput').setAttribute('aria-invalid',!!error);}return error;}
function syncControls(){
 $('effectName').textContent=selected.name;for(const k of ['title','subtitle'])$(k+'Input').value=settings[k];for(const k of ['ratio','duration','intensity','scale'])$(k).value=settings[k];
 $('titleInput').placeholder=selected.id==='bars'?'例如 12,28,45,68':selected.category==='data'?'填写数值':'写下你的标题';$('titleInput').disabled=selected.category==='transition';$('subtitleInput').disabled=selected.category==='transition';$('uploadLabel').hidden=selected.category==='transition';
 $('uploadLabel').querySelector('span').textContent=settings.image?'✓ 图片已添加（仅本地）':'＋ 添加 Logo / 图片';$('removeImage').hidden=!settings.image;
 document.querySelectorAll('[data-position]').forEach(b=>b.classList.toggle('selected',b.dataset.position===settings.position));document.querySelectorAll('.swatch').forEach(b=>{b.classList.toggle('selected',b.dataset.color===settings.color);b.setAttribute('aria-pressed',b.dataset.color===settings.color);});
 const [w,h]=dimensions(settings.ratio,540);$('preview').width=w;$('preview').height=h;$('previewStage').style.aspectRatio=`${w}/${h}`;$('previewStage').style.width=settings.ratio==='9:16'?'min(calc(100% - 40px), 152px)':settings.ratio==='1:1'?'min(calc(100% - 40px), 270px)':'calc(100% - 40px)';$('previewStage').style.minHeight='0';$('previewStage').style.marginInline='auto';$('dimensions').textContent=dimensions(settings.ratio,1080).join(' × ');validate();syncFavorite();draw();
}
function draw(){renderFrame($('preview'),selected,settings,progress);$('scrub').value=Math.round(progress*1000);$('timeDisplay').textContent=`${(progress*settings.duration).toFixed(1)} / ${settings.duration.toFixed(1)}s`;$('playButton').textContent=playing?'Ⅱ':'▶';$('playButton').setAttribute('aria-label',playing?'暂停预览':'播放预览');}
function tick(time){const delta=lastTime?Math.min(time-lastTime,100):0;lastTime=time;if(playing&&!document.hidden&&!$('exportDialog').open&&!$('helpDialog').open)progress=(progress+delta/(settings.duration*1000))%1;draw();if(hover)renderFrame(hover.canvas,hover.e,defaults(hover.e),((time-hover.start)%3000)/3000);requestAnimationFrame(tick);}
for(const [id,icon,name] of categories){const b=document.createElement('button');b.className='nav-item';b.dataset.category=id;const span=document.createElement('span');span.textContent=icon;b.append(span,document.createTextNode(name));b.onclick=()=>{category=id;view='all';renderLibrary();};$('categories').append(b);}
for(const [color,name] of colors){const b=document.createElement('button');b.className='swatch';b.style.background=color;b.dataset.color=color;b.setAttribute('aria-label',`配色：${name}`);b.onclick=()=>{settings.color=color;syncControls();};$('palette').append(b);}
$('totalCount').textContent=effects.length;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;category='all';renderLibrary();});$('search').oninput=e=>{query=e.target.value.trim();renderLibrary();};$('styleFilter').onchange=e=>{style=e.target.value;renderLibrary();};$('clearFilters').onclick=()=>{query='';style='all';category='all';view='all';$('search').value='';$('styleFilter').value='all';renderLibrary();};$('favoriteButton').onclick=()=>favorite(selected.id);
for(const k of ['title','subtitle'])$(k+'Input').oninput=e=>{settings[k]=e.target.value;validate();draw();};for(const k of ['ratio','duration','intensity','scale'])$(k).oninput=e=>{settings[k]=k==='ratio'?e.target.value:+e.target.value;syncControls();};document.querySelectorAll('[data-position]').forEach(b=>b.onclick=()=>{settings.position=b.dataset.position;syncControls();});
document.querySelectorAll('[data-bg]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-bg]').forEach(x=>x.classList.toggle('selected',x===b));$('previewStage').className=`preview-stage ${b.dataset.bg}`;});$('playButton').onclick=()=>{playing=!playing;draw();};$('scrub').oninput=e=>{playing=false;progress=+e.target.value/1000;draw();};$('replayButton').onclick=()=>{progress=0;playing=true;draw();};$('resetButton').onclick=()=>{settings=defaults(selected);$('imageUpload').value='';syncControls();notify('已恢复该动效的默认内容与样式');};
$('imageUpload').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024){notify('请选择 10 MB 以内的 PNG、JPG 或 WebP 图片');e.target.value='';return;}const url=URL.createObjectURL(file);try{const im=new Image();im.src=url;await im.decode();if(im.width*im.height>24000000)throw new Error('图片尺寸过大，请缩小到 2400 万像素以内');settings.image=im;syncControls();notify('图片已加入，未上传到服务器');}catch(error){notify(error.message||'图片无法读取，请重新选择');}finally{URL.revokeObjectURL(url);e.target.value='';}};$('removeImage').onclick=()=>{settings.image=null;syncControls();};
for(const id of ['helpButton','guideButton'])$(id).onclick=()=>$('helpDialog').showModal();document.querySelectorAll('#helpDialog .close-dialog').forEach(b=>b.onclick=()=>$('helpDialog').close());
function exportSummary(){const [w,h]=dimensions(settings.ratio,+$('exportResolution').value);const frame=document.querySelector('[name=format]:checked').value==='frame';$('exportFps').disabled=frame;$('exportSummary').textContent=frame?`${w} × ${h} · 当前 ${(progress*settings.duration).toFixed(2)} 秒 · RGBA 透明 PNG`:`${w} × ${h} · ${settings.duration} 秒 · ${+$('exportFps').value*settings.duration} 帧 · 透明 PNG / ZIP`;document.querySelectorAll('.format-option').forEach(el=>el.classList.toggle('selected',!!el.querySelector('input:checked')));}
function openExport(){if(validate()){$('titleInput').focus();notify('内容需要调整，请查看主标题下方提示');return;}$('exportError').hidden=true;$('exportProgress').hidden=true;exportSummary();$('exportDialog').showModal();}$('exportButton').onclick=openExport;for(const el of document.querySelectorAll('[name=format],#exportResolution,#exportFps'))el.onchange=exportSummary;
function closeExport(){if(exportController){exportController.abort();$('cancelExport').textContent='正在取消…';}else $('exportDialog').close();}$('cancelExport').onclick=closeExport;document.querySelector('#exportDialog .close-dialog').onclick=closeExport;$('exportDialog').addEventListener('cancel',e=>{if(exportController){e.preventDefault();closeExport();}});
$('startExport').onclick=async()=>{
 if(exportController)return;const controller=new AbortController();exportController=controller;const snapshot={...settings},effect=selected;const canvas=document.createElement('canvas');[canvas.width,canvas.height]=dimensions(snapshot.ratio,+$('exportResolution').value);const format=document.querySelector('[name=format]:checked').value;const fps=+$('exportFps').value;
 const controls=[...document.querySelectorAll('#exportDialog input,#exportDialog select,#startExport')];controls.forEach(el=>el.disabled=true);$('cancelExport').textContent='取消生成';$('exportError').hidden=true;$('exportProgress').hidden=false;const bar=$('exportProgress').querySelector('progress'),status=$('exportProgress').querySelector('p');bar.value=0;status.textContent='正在准备透明画布…';
 try{let blob,metadata;if(format==='frame'){renderFrame(canvas,effect,snapshot,progress);blob=await toPNG(canvas);metadata={width:canvas.width,height:canvas.height,frameCount:1,format:'PNG'};}else{const result=await exportSequence({canvas,effect,settings:snapshot,fps,render:renderFrame,signal:controller.signal,onProgress:(done,total)=>{bar.value=done/total*100;status.textContent=`正在生成 ${done} / ${total} 帧，请保持此页面打开`;}});blob=result.blob;metadata=result.metadata;}
 if(controller.signal.aborted)throw new DOMException('已取消','AbortError');const filename=`motion-${effect.id}-${canvas.width}x${canvas.height}${format==='sequence'?`-${fps}fps.zip`:'.png'}`;if(lastDownloadUrl)URL.revokeObjectURL(lastDownloadUrl);lastDownloadUrl=download(blob,filename);lastExport={...metadata,filename,bytes:blob.size};bar.value=100;status.textContent=`已生成 ${filename}（${(blob.size/1024/1024).toFixed(2)} MB）。`;const link=document.createElement('a');link.href=lastDownloadUrl;link.download=filename;link.textContent='未自动下载？点击保存文件';link.style.cssText='display:block;color:#c4f36b;margin-top:10px';status.append(link);notify('透明素材已生成，请查看浏览器下载');
 }catch(error){if(error.name==='AbortError'){status.textContent='已取消生成，没有下载文件。';notify('导出已取消');}else{$('exportError').textContent=error.message||'导出失败，请降低分辨率重试。';$('exportError').hidden=false;}}
 finally{exportController=null;controls.forEach(el=>el.disabled=false);$('cancelExport').textContent='关闭';exportSummary();}
};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('search').focus();}if(e.key==='?'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]'))$('helpDialog').showModal();});renderLibrary();syncControls();requestAnimationFrame(tick);
// Optional WebMCP uses the same state/actions as the UI and never starts a download.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
register({name:'read_motion_workbench',title:'查看动效工作台',description:'Read available animation IDs and visible settings without changing the workbench.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(input&&Object.keys(input).length)throw new Error('此工具不接受参数');return {effects:effects.map(({id,name,category})=>({id,name,category})),...state()};}});
register({name:'configure_motion',title:'选择并配置动效',description:'Select a template and set its content in the visible workbench. Does not export or download.',inputSchema:{type:'object',properties:{effectId:{type:'string',enum:effects.map(e=>e.id)},title:{type:'string',maxLength:40},subtitle:{type:'string',maxLength:70},ratio:{type:'string',enum:['16:9','9:16','1:1']}},required:['effectId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||Object.keys(input).some(k=>!['effectId','title','subtitle','ratio'].includes(k)))throw new Error('参数无效');const effect=effects.find(e=>e.id===input.effectId);if(!effect)throw new Error('未找到该动效');if(input.ratio&&!['16:9','9:16','1:1'].includes(input.ratio))throw new Error('画幅无效');for(const [key,max]of [['title',40],['subtitle',70]])if(input[key]!==undefined&&(typeof input[key]!=='string'||input[key].length>max))throw new Error('文字长度无效');const error=validateContent(effect,input.title??effect.title);if(error)throw new Error(error);selectEffect(effect.id);for(const key of ['title','subtitle','ratio'])if(input[key]!==undefined)settings[key]=input[key];syncControls();return state();}});addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
